INSERT INTO `attractions` (`id`, `content_id`, `title`, `content_type`, `area_code`, `sigungu_code`, `address`, `description`, `latitude`, `longitude`, `image_url`, `source_updated_at`, `synced_at`) VALUES (25951,2761649,'대관령아름다운펜션',32,32,15,'강원특별자치도 평창군 대관령면 송전1길 32',NULL,37.66396692,128.71254990,'http://tong.visitkorea.or.kr/cms/resource/71/2764971_image2_1.jpg','20251110141935','2026-11-06 02:07:39'),(25952,2761650,'대관령그린필드펜션',32,32,15,'강원특별자치도 평창군 대관령면 차항길 192-77 (차항리)',NULL,37.70974739,128.69435570,'http://tong.visitkorea.or.kr/cms/resource/57/2764557_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25953,2761652,'단양 사계절썰매장',28,33,2,'충청북도 단양군 단양읍 삼봉로 421-59',NULL,36.98721590,128.35551605,'http://tong.visitkorea.or.kr/cms/resource/86/2762186_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25954,2761653,'잠두봉더나인',39,1,13,'서울특별시 마포구 마포나루길 582 (합정동)',NULL,37.54509159,126.90835024,'http://tong.visitkorea.or.kr/cms/resource/87/2790187_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25955,2761661,'구강사',12,1,2,'서울특별시 강동구 천중로 64 (천호동)','서울 강동구 천호동에 있는 구강사는 서울 동부지역 천태법음 요람이자 포교도량으로 대한불교 천태종 사찰이다. 5층 단독 건물로 5층에 법당이 있으며, 3층에는 교육시설인  ‘금강유치원’이 있으며 옥상에는 정원이 있다. 정기법회는 매월 넷째 주 일요일 오전 11시에 열리고 있으며 불교대학도 운영되고 있다. 지하철 5호선 8호선 천호역 3번 출구 천인중학교 맞은편에 있다.',37.54491502,127.12886072,'http://tong.visitkorea.or.kr/cms/resource/83/3463583_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25956,2761662,'명락사',12,1,5,'서울특별시 관악구 청룡1길 11','서울 관악구 청룡동에 있는 명락사는 관악산 줄기의 끝자락 도심 상업지역에 있다. 40여 년 넘게 서울 서남권의 포교 활동과 다문화가정을 위한 포교에 관심을 기울이고 있는 사찰이다. 청년회가 활성화되어 있으며, 토요일 저녁 8시 30분부터 정기 법회를 갖는다. 2호선 봉천역과 서울대입구역 중간지점에 있다.',37.48146357,126.94702074,'http://tong.visitkorea.or.kr/cms/resource/83/2790183_image2_1.jpg','20250328142944','2026-11-06 02:07:32'),(25957,2761669,'연하협구름다리',12,33,1,'충청북도 괴산군 칠성면 명태재로미루길 100',NULL,36.73909869,127.83785286,'http://tong.visitkorea.or.kr/cms/resource/61/2762161_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25958,2761671,'로얄장모텔',32,32,15,'강원특별자치도 평창군 평창읍 백오1길 44 (하리, 로얄모텔)',NULL,37.36823110,128.39437913,'http://tong.visitkorea.or.kr/cms/resource/27/2769427_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25959,2761675,'산아래석갈비',39,33,7,'충청북도 제천시 백운면 금봉로 182',NULL,37.14593067,128.04187014,NULL,'20250313172650','2026-11-06 02:07:41'),(25960,2761677,'초원의 집',12,33,1,'충청북도 괴산군 칠성면 연풍로쌍곡길 25-6',NULL,36.77850894,127.88631962,'http://tong.visitkorea.or.kr/cms/resource/71/2762171_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25961,2761681,'스시히어로',39,33,10,'충청북도 청주시 흥덕구 대농로 33 (복대동)',NULL,36.64249955,127.42593415,NULL,'20251125130634','2026-11-06 02:07:41'),(25962,2761684,'충청도양반길 2코스',28,33,1,'충청북도 괴산군 칠성면 칠성로10길 547',NULL,36.73459672,127.85356824,'http://tong.visitkorea.or.kr/cms/resource/75/2762175_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25963,2761686,'정가네명태',39,33,11,'충청북도 충주시 노은면 감노로 1655',NULL,37.04224057,127.78075217,NULL,NULL,'2026-11-06 00:48:43'),(25964,2761687,'중앙 어울림 시장',38,33,11,'충청북도 충주시 예성로 168 (성서동)',NULL,36.97198758,127.93365432,'http://tong.visitkorea.or.kr/cms/resource/59/2761659_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25965,2761688,'옥성저수지',12,33,8,'충청북도 진천군 문백면 옥성리',NULL,36.79714888,127.44971662,'http://tong.visitkorea.or.kr/cms/resource/64/3355464_image2_1.JPG',NULL,'2026-11-06 00:48:43'),(25966,2761690,'우림정원',12,33,11,'충청북도 충주시 엄정면 삼실길 42',NULL,37.07914970,127.90370116,NULL,NULL,'2026-11-06 00:48:43'),(25967,2761694,'세일 컨트리클럽',28,33,11,'충청북도 충주시 신니면 동락길 207',NULL,37.01994678,127.67583446,'http://tong.visitkorea.or.kr/cms/resource/82/2761682_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25968,2761695,'충주호 종댕이길 출렁다리',12,33,11,'충청북도 충주시 종민동',NULL,36.99135026,127.98892102,'http://tong.visitkorea.or.kr/cms/resource/71/3560671_image2_1.JPG','20251103160139','2026-11-06 02:07:41'),(25969,2761699,'수주팔봉 야영지',28,33,11,'충청북도 충주시 대소원면 문주리 산 1-1',NULL,36.89952071,127.92271848,'http://tong.visitkorea.or.kr/cms/resource/76/2761676_image2_1.jpg',NULL,'2026-11-06 00:48:43'),(25970,2761709,'봉은사',12,33,11,'충청북도 충주시 소태면 주치길 135-45',NULL,37.12336846,127.84205544,NULL,NULL,'2026-11-